files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  position: relative;
  padding-top: 94px;
}

.container {
  width: 100%;
  padding-right: 15px;
  padding-left: 15px;
  margin-right: auto;
  margin-left: auto;
}

@media (min-width: 576px) {
  .container {
    max-width: 540px;
  }
}
@media (min-width: 768px) {
  .container {
    max-width: 720px;
  }
}
@media (min-width: 992px) {
  .container {
    max-width: 960px;
  }
}
@media (min-width: 1200px) {
  .container {
    max-width: 1140px;
  }
}

/* Navigation */
.nav {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  padding: 20px 0;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  display: inline-block;
  text-decoration: none;
  color: var(--vt-accent);
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin: 0 30px;
  padding: 0;
}

.logo strong {
  color: var(--vt-ink-soft);
  font-size: 12px;
  position: relative;
  bottom: 5px;
  display: block;
}

.brand {
  /* Brand component may apply its own styles, we override minimal */
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
  padding: 0.5rem 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  padding-top: 0;
}

.heroInner {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.slider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  -webkit-overflow-scrolling: touch;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  object-fit: cover;
  width: 100%;
  height: 100%;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: none;
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.animatedInfo {
  display: inline-block;
  vertical-align: top;
  min-width: 250px;
  position: relative;
}

.animatedItem {
  color: var(--vt-accent);
  display: block;
  opacity: 0;
  overflow: hidden;
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  animation: BottomTotop 6s linear infinite 0s;
}

.animatedItem:nth-child(2) {
  animation-delay: 2s;
}

.animatedItem:nth-child(3) {
  animation-delay: 4s;
}

@keyframes BottomTotop {
  0% { opacity: 0; }
  5% { opacity: 0; transform: translateY(5px); }
  10% { opacity: 1; transform: translateY(0); }
  25% { opacity: 1; transform: translateY(0); }
  30% { opacity: 0; transform: translateY(5px); }
  80% { opacity: 0; }
  100% { opacity: 0; }
}

.heroDesc {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  position: relative;
  padding: 0 30px;
  box-sizing: border-box;
  margin-right: 1.5rem;
  overflow: hidden;
  text-transform: uppercase;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
  right: 0;
  text-align: center;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
}

.phoneIcon {
  display: inline-block;
  width: 0.7em;
  height: 0.7em;
  border: 1px solid currentColor;
  border-radius: 50%;
  position: relative;
  margin-right: 0.3em;
}

/* About */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutText {
  flex: 0 0 100%;
  max-width: 100%;
}

.sectionTitle {
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.aboutPara {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.center {
  text-align: center;
}

/* Gallery */
.gallerySection {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 0 0 50%;
  max-width: 50%;
  padding: 0;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* Timeline */
.timelineSection {
  padding-bottom: 0;
}

.timeline {
  position: relative;
  margin-top: 3rem;
}

.timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  margin-bottom: 3rem;
}

.timelineNode.even {
  flex-direction: row;
}

.timelineNode.odd {
  flex-direction: row-reverse;
}

.timelineContent {
  flex: 0 0 41.666667%;
  max-width: 41.666667%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 24px;
  font-weight: 600;
  position: relative;
}

.timelineDesc {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
}

.timelineIconWrap {
  flex: 0 0 8.333333%;
  max-width: 8.333333%;
  position: relative;
  z-index: 100;
  display: flex;
  justify-content: center;
}

.timelineIconWrap::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  display: block;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, 0);
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  z-index: 1;
}

.timelineIcon {
  position: relative;
  z-index: 100;
  font-size: 32px;
  color: var(--vt-accent);
  display: block;
  text-align: center;
  line-height: 80px;
  width: 80px;
  height: 80px;
}

.timelineDate {
  flex: 0 0 41.666667%;
  max-width: 41.666667%;
  padding: 1.5rem 0;
}

.timelineNode.even .timelineDate {
  text-align: right;
  padding-right: 15px;
}

.timelineNode.odd .timelineDate {
  text-align: left;
  padding-left: 15px;
}

.timelineNode.even .timelineContent {
  margin-left: auto;
}

.timelineNode.odd .timelineContent {
  margin-right: auto;
}

.timelineNode.even .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.odd .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
}

.footerCol {
  flex: 0 0 100%;
  max-width: 100%;
  margin-bottom: 2rem;
}

.footerTitle {
  font-size: 20px;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.hours,
.addressLine,
.copyright {
  color: var(--vt-ink-soft);
  font-size: 16px;
  margin-bottom: 0.5rem;
}

.addressLine a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.addressLine a:hover {
  color: var(--vt-accent);
}

.socialLinks {
  /* Container for SocialLinks component */
}

.copyrightCol {
  margin-top: 2rem;
}

.copyright {
  font-size: 14px;
  color: var(--vt-ink-soft);
}

/* Responsive */
@media screen and (min-width: 1600px) {
  .heroInner {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .heroInner {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    left: 0;
    width: auto;
    margin-bottom: 0;
    padding: 2rem;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .heroTitle {
    font-size: 38px;
  }

  .sectionTitle {
    font-size: 32px;
  }

  .timeline::before {
    top: 60px;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .animatedInfo {
    min-width: 125px;
  }

  .timelineNode.even,
  .timelineNode.odd {
    flex-direction: column;
  }

  .timeline::before {
    left: 33px;
    height: 90%;
    transform: translateX(-50%);
  }

  .timelineIconWrap {
    position: absolute;
    left: 0;
    top: 60px;
  }

  .timelineContent,
  .timelineDate {
    flex: 0 0 100%;
    max-width: 100%;
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding-left: 60px;
    padding-right: 0;
  }

  .timelineNode.even .timelineDate,
  .timelineNode.odd .timelineDate {
    text-align: left;
    padding-left: 60px;
  }

  .timelineNode.even .timelineTitle::after,
  .timelineNode.odd .timelineTitle::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  .timelineIconWrap::before {
    width: 75px;
    height: 75px;
  }

  .timelineIcon {
    line-height: 75px;
    width: 75px;
    height: 75px;
  }

  .galleryItem {
    flex: 0 0 100%;
    max-width: 100%;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
    height: 87%;
  }

  .timelineIconWrap {
    left: -10px;
  }

  .timelineIconWrap::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    line-height: 70px;
    width: 70px;
    height: 70px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
